#!/usr/bin/env python3
"""Build the final HTML report from pre-computed analysis results."""
import json

with open('/app/analyze_results.json') as f:
    data = json.load(f)

k = data['kpis']
charts = data['charts']
orbit_table = data['orbit_table']
const_table = data['const_table']
inc_stats = data['inc_stats']
ecc_stats = data['ecc_stats']
mm_stats = data['mm_stats']
post2020 = data['post2020_detail']
decade_table = data['decade_table']
epoch_range = data['epoch_range']

# ─── Helper: table rows ──────────────────────────────────────────────────────
def orbit_rows():
    rows = []
    for r in orbit_table:
        rows.append(f"""
        <tr>
          <td><span class="badge badge-{r['Regime'].lower()}">{r['Regime']}</span></td>
          <td class="num">{int(r['Count']):,}</td>
          <td class="num">{r['Share (%)']:.1f}%</td>
          <td class="desc">{r.get('Description','')}</td>
        </tr>""")
    return ''.join(rows)

def const_rows():
    rows = []
    for i, r in enumerate(const_table):
        pct = r['Share of Fleet (%)']
        bar_w = min(100, pct / const_table[0]['Share of Fleet (%)'] * 100)
        highlight = ' highlight-row' if i == 0 else ''
        rows.append(f"""
        <tr class="{highlight}">
          <td>{r['Constellation / Operator']}</td>
          <td class="num">{int(r['Active Satellites']):,}</td>
          <td class="num">{pct:.2f}%</td>
          <td style="min-width:120px">
            <div class="bar-bg"><div class="bar-fill" style="width:{bar_w:.1f}%"></div></div>
          </td>
        </tr>""")
    return ''.join(rows)

def post2020_rows():
    rows = []
    for yr in sorted(post2020.keys(), reverse=True):
        rows.append(f"<tr><td>{yr}</td><td class='num'>{post2020[yr]:,}</td></tr>")
    return ''.join(rows)

# ─── HTML ────────────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>Active Satellites in Earth Orbit — 2026 Catalog Analysis</title>
<style>
  :root {{
    --blue:       #1a56db;
    --dark-blue:  #1e3a5f;
    --accent:     #f59e0b;
    --green:      #10b981;
    --red:        #ef4444;
    --gray:       #6b7280;
    --light:      #f1f5f9;
    --white:      #ffffff;
    --text:       #1f2937;
    --muted:      #9ca3af;
    --border:     #e5e7eb;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    font-size: 14px;
    color: var(--text);
    background: #f8fafc;
    line-height: 1.65;
  }}

  /* ── Cover ── */
  .cover {{
    background: linear-gradient(135deg, var(--dark-blue) 0%, #2563eb 60%, #1a56db 100%);
    color: white;
    padding: 64px 80px 48px;
    position: relative;
    overflow: hidden;
  }}
  .cover::after {{
    content: '';
    position: absolute;
    right: -80px; top: -80px;
    width: 400px; height: 400px;
    border-radius: 50%;
    background: rgba(255,255,255,0.04);
  }}
  .cover-tag {{
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: rgba(255,255,255,0.6);
    margin-bottom: 16px;
  }}
  .cover h1 {{
    font-size: 34px;
    font-weight: 800;
    line-height: 1.2;
    margin-bottom: 12px;
    max-width: 680px;
  }}
  .cover .subtitle {{
    font-size: 15px;
    color: rgba(255,255,255,0.75);
    max-width: 580px;
    margin-bottom: 36px;
  }}
  .cover-meta {{
    display: flex;
    gap: 32px;
    font-size: 12px;
    color: rgba(255,255,255,0.55);
  }}
  .cover-meta span b {{ color: rgba(255,255,255,0.9); }}

  /* ── KPI Banner ── */
  .kpi-banner {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 0;
    background: white;
    border-bottom: 3px solid var(--blue);
    box-shadow: 0 2px 12px rgba(0,0,0,0.08);
  }}
  .kpi-card {{
    padding: 22px 20px;
    border-right: 1px solid var(--border);
    text-align: center;
  }}
  .kpi-card:last-child {{ border-right: none; }}
  .kpi-value {{
    font-size: 28px;
    font-weight: 800;
    color: var(--blue);
    line-height: 1.1;
    margin-bottom: 4px;
  }}
  .kpi-value.accent {{ color: var(--accent); }}
  .kpi-value.green  {{ color: var(--green); }}
  .kpi-value.red    {{ color: var(--red); }}
  .kpi-label {{
    font-size: 10.5px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    color: var(--gray);
  }}
  .kpi-sub {{
    font-size: 10px;
    color: var(--muted);
    margin-top: 3px;
  }}

  /* ── Layout ── */
  .container {{
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 40px;
  }}
  .section {{
    padding: 48px 0 24px;
  }}
  .section + .section {{
    border-top: 1px solid var(--border);
  }}

  /* ── Section headers ── */
  .section-num {{
    display: inline-block;
    background: var(--blue);
    color: white;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1px;
    padding: 2px 8px;
    border-radius: 3px;
    margin-bottom: 6px;
  }}
  h2 {{
    font-size: 22px;
    font-weight: 800;
    color: var(--dark-blue);
    margin-bottom: 8px;
  }}
  h3 {{
    font-size: 15px;
    font-weight: 700;
    color: var(--dark-blue);
    margin: 24px 0 10px;
  }}
  .section-intro {{
    font-size: 14px;
    color: var(--gray);
    max-width: 780px;
    margin-bottom: 24px;
  }}

  /* ── Charts ── */
  .chart-grid {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 24px 0;
  }}
  .chart-grid.single {{
    grid-template-columns: 1fr;
  }}
  .chart-card {{
    background: white;
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.05);
  }}
  .chart-card img {{
    width: 100%;
    height: auto;
    display: block;
    border-radius: 4px;
  }}
  .chart-caption {{
    font-size: 11px;
    color: var(--muted);
    text-align: center;
    margin-top: 10px;
    font-style: italic;
  }}

  /* ── Tables ── */
  .tbl-wrap {{
    overflow-x: auto;
    margin: 16px 0;
  }}
  table {{
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    background: white;
    border: 1px solid var(--border);
    border-radius: 10px;
    overflow: hidden;
    box-shadow: 0 1px 4px rgba(0,0,0,0.05);
  }}
  thead tr {{
    background: var(--dark-blue);
    color: white;
  }}
  thead th {{
    padding: 11px 14px;
    text-align: left;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
  }}
  tbody tr:nth-child(even) {{ background: var(--light); }}
  tbody tr:hover {{ background: #eff6ff; }}
  td {{
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
    vertical-align: middle;
  }}
  td.num {{
    text-align: right;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    font-family: 'SF Mono', 'Consolas', monospace;
    font-size: 13px;
  }}
  td.desc {{ color: var(--gray); font-size: 12px; }}
  tr.highlight-row {{ background: #eff6ff !important; }}
  tr.highlight-row td {{ font-weight: 600; color: var(--dark-blue); }}

  /* ── Badges ── */
  .badge {{
    display: inline-block;
    padding: 2px 9px;
    border-radius: 99px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.3px;
  }}
  .badge-leo {{ background:#dbeafe; color:#1d4ed8; }}
  .badge-geo {{ background:#fef3c7; color:#92400e; }}
  .badge-meo {{ background:#d1fae5; color:#065f46; }}
  .badge-heo {{ background:#fee2e2; color:#991b1b; }}
  .badge-other {{ background:#f3f4f6; color:#374151; }}
  .badge-unknown {{ background:#f3f4f6; color:#9ca3af; }}

  /* ── Bar mini ── */
  .bar-bg {{
    background: var(--light);
    border-radius: 4px;
    height: 8px;
    width: 100%;
  }}
  .bar-fill {{
    background: var(--blue);
    border-radius: 4px;
    height: 100%;
  }}

  /* ── Callout ── */
  .callout {{
    border-left: 4px solid var(--blue);
    background: #eff6ff;
    padding: 14px 18px;
    border-radius: 0 8px 8px 0;
    margin: 20px 0;
    font-size: 13.5px;
    color: var(--dark-blue);
  }}
  .callout.amber {{
    border-left-color: var(--accent);
    background: #fffbeb;
    color: #78350f;
  }}
  .callout.green {{
    border-left-color: var(--green);
    background: #ecfdf5;
    color: #064e3b;
  }}
  .callout strong {{ font-weight: 700; }}

  /* ── Stats grid ── */
  .stats-grid {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 12px;
    margin: 16px 0;
  }}
  .stat-cell {{
    background: white;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 14px 12px;
    text-align: center;
  }}
  .stat-val {{
    font-size: 20px;
    font-weight: 800;
    color: var(--blue);
    margin-bottom: 4px;
  }}
  .stat-lbl {{
    font-size: 10.5px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--gray);
    font-weight: 600;
  }}

  /* ── Two-col text ── */
  .two-col {{
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
    margin: 16px 0;
  }}

  /* ── Footer ── */
  footer {{
    background: var(--dark-blue);
    color: rgba(255,255,255,0.5);
    text-align: center;
    padding: 24px;
    font-size: 11px;
    margin-top: 48px;
  }}
  footer b {{ color: rgba(255,255,255,0.85); }}

  /* ── TOC ── */
  .toc {{
    background: white;
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px 28px;
    margin: 32px 0 0;
    display: inline-block;
    min-width: 320px;
  }}
  .toc-title {{
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--gray);
    margin-bottom: 12px;
  }}
  .toc ol {{
    margin: 0;
    padding-left: 18px;
    font-size: 13px;
  }}
  .toc li {{ margin-bottom: 6px; }}
  .toc a {{ color: var(--blue); text-decoration: none; }}
  .toc a:hover {{ text-decoration: underline; }}

  @media (max-width: 760px) {{
    .kpi-banner {{ grid-template-columns: repeat(2,1fr); }}
    .chart-grid {{ grid-template-columns: 1fr; }}
    .stats-grid {{ grid-template-columns: repeat(3,1fr); }}
    .two-col {{ grid-template-columns: 1fr; }}
    .cover {{ padding: 40px 24px 32px; }}
    .container {{ padding: 0 16px; }}
  }}
</style>
</head>
<body>

<!-- ══════════════════════ COVER ══════════════════════ -->
<div class="cover">
  <div class="cover-tag">Orbital Analytics Report · April 2026</div>
  <h1>Active Satellites in Earth Orbit<br>2026 Catalog Analysis</h1>
  <p class="subtitle">
    A data-driven examination of the {k['total']:,} active satellites tracked by CelesTrak/NORAD,
    covering orbital regime distribution, constellation composition, launch trends,
    and key orbital parameters — produced for space-industry analysts and policy advisors.
  </p>
  <div class="cover-meta">
    <span><b>Dataset:</b> CelesTrak / NORAD TLE Catalog</span>
    <span><b>EPOCH Range:</b> {epoch_range}</span>
    <span><b>Rows:</b> {k['total']:,} active satellites</span>
    <span><b>Published:</b> April 2026</span>
  </div>
</div>

<!-- ══════════════════════ KPI BANNER ══════════════════════ -->
<div class="kpi-banner">
  <div class="kpi-card">
    <div class="kpi-value">{k['total']:,}</div>
    <div class="kpi-label">Total Active Satellites</div>
    <div class="kpi-sub">As of EPOCH range</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value accent">{k['leo_share']}%</div>
    <div class="kpi-label">LEO Share</div>
    <div class="kpi-sub">{k['leo_count']:,} satellites · MM &gt; 14 rev/day</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value red">{k['starlink']:,}</div>
    <div class="kpi-label">Starlink Fleet Size</div>
    <div class="kpi-sub">{k['starlink_pct']}% of total fleet</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value green">{k['median_inc']}°</div>
    <div class="kpi-label">Median Inclination</div>
    <div class="kpi-sub">Degrees above equatorial plane</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-value">{k['post2020']:,}</div>
    <div class="kpi-label">Launched Since 2020</div>
    <div class="kpi-sub">{k['post2020_pct']}% of active fleet</div>
  </div>
</div>

<!-- ══════════════════════ MAIN BODY ══════════════════════ -->
<div class="container">

  <!-- TOC -->
  <div class="toc">
    <div class="toc-title">Contents</div>
    <ol>
      <li><a href="#overview">Catalog Overview &amp; Key Figures</a></li>
      <li><a href="#orbit-regime">Orbital Regime Classification</a></li>
      <li><a href="#constellation">Major Constellation &amp; Operator Breakdown</a></li>
      <li><a href="#launch-trends">Launch Year Trends</a></li>
      <li><a href="#orbital-char">Orbital Parameter Deep Dive</a></li>
      <li><a href="#conclusions">Key Takeaways &amp; Outlook</a></li>
    </ol>
  </div>

  <!-- ═══ SECTION 1 — OVERVIEW ═══ -->
  <div class="section" id="overview">
    <div class="section-num">SECTION 01</div>
    <h2>Catalog Overview &amp; Key Figures</h2>
    <p class="section-intro">
      The CelesTrak/NORAD active-satellite catalog captures {k['total']:,} operational spacecraft as of
      {epoch_range}. This snapshot encompasses the full spectrum of Earth-orbital missions —
      from mega-constellations to singular scientific probes — and forms the authoritative basis
      for all figures in this report.
    </p>

    <div class="callout">
      <strong>Data coverage:</strong> Every metric, chart, and percentage in this report is computed
      directly from the {k['total']:,}-row dataset. No values have been imputed or externally sourced.
      Orbital classification uses MEAN_MOTION thresholds as described in Section 2.
    </div>

    <div class="two-col">
      <div>
        <h3>Fleet Composition at a Glance</h3>
        <p style="color:var(--gray); font-size:13px; margin-bottom:14px;">
          LEO dominates the fleet at <strong>{k['leo_share']}%</strong> of all active satellites,
          driven overwhelmingly by Starlink. GEO hosts the traditional communications and weather
          satellite fleet. MEO carries navigation constellations (GPS, GLONASS, Galileo, BeiDou).
          HEO represents a small minority of highly elliptical surveillance and communication missions.
        </p>
        <div class="callout amber">
          <strong>Starlink effect:</strong> {k['starlink']:,} of {k['total']:,} active satellites
          ({k['starlink_pct']}%) belong to SpaceX's Starlink mega-constellation. This single operator
          skews every aggregate statistic — inclination, mean motion, LEO share — dramatically toward
          its chosen shell parameters (~53° inclination, ~15 rev/day). All subsequent analysis
          segments results with this context in mind.
        </div>
      </div>
      <div>
        <h3>EPOCH &amp; Data Freshness</h3>
        <p style="color:var(--gray); font-size:13px; margin-bottom:14px;">
          The EPOCH field records when each orbital element set was last updated. The full range
          spans <strong>{epoch_range}</strong>, indicating that the vast majority of TLE records
          are current within a narrow recent window — consistent with the CelesTrak practice of
          refreshing elements daily for active payloads.
        </p>
        <h3>Mean Motion &amp; Inclination Summary</h3>
        <div class="stats-grid" style="grid-template-columns:repeat(2,1fr);">
          <div class="stat-cell">
            <div class="stat-val">{mm_stats['mean']:.2f}</div>
            <div class="stat-lbl">Mean · Rev/Day</div>
