"""Build the final HTML report from pre-computed analysis results."""
import json

with open('/app/analyze_results.json') as f:
    data = json.load(f)

k = data['kpis']
charts = data['charts']
orbit_table = data['orbit_table']
const_table = data['const_table']
inc_stats = data['inc_stats']
ecc_stats = data['ecc_stats']
mm_stats = data['mm_stats']
post2020 = data['post2020_detail']
decade_table = data['decade_table']
epoch_range = data['epoch_range']

# ─── Helper: table rows ──────────────────────────────────────────────────────
def orbit_rows():
    rows = []
    for r in orbit_table:
        rows.append(f"""
        <tr>
          <td><span class="badge badge-{r['Regime'].lower()}">{r['Regime']}</span></td>
          <td class="num">{int(r['Count']):,}</td>
          <td class="num">{r['Share (%)']:.1f}%</td>
          <td class="desc">{r.get('Description','')}</td>
        </tr>""")
    return ''.join(rows)

def const_rows():
    rows = []
    for i, r in enumerate(const_table):
        pct = r['Share of Fleet (%)']
        bar_w = min(100, pct / const_table[0]['Share of Fleet (%)'] * 100)
        highlight = ' highlight-row' if i == 0 else ''
        rows.append(f"""
        <tr class="{highlight}">
          <td>{r['Constellation / Operator']}</td>
          <td class="num">{int(r['Active Satellites']):,}</td>
          <td class="num">{pct:.2f}%</td>
          <td style="min-width:120px">
            <div class="bar-bg"><div class="bar-fill" style="width:{bar_w:.1f}%"></div></div>
          </td>
        </tr>""")
    return ''.join(rows)

def post2020_rows():
    rows = []
    for yr in sorted(post2020.keys(), reverse=True):
        rows.append(f"<tr><td>{yr}</td><td class='num'>{post2020[yr]:,}</td></tr>")
    return ''.join(rows)

